/* --- Promo Banner (Brand Collab, etc.) --- */
.promo-banner {
  border-radius: var(--radius-xl);
  overflow: hidden;
  padding: var(--spacing-3xl);
  text-align: center;
  margin: 0 auto;
  max-width: var(--max-width);
}

.promo-banner--dark {
  background: var(--color-dark);
  color: var(--color-white);
}

.promo-banner--gradient {
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
  color: var(--color-white);
}

.promo-banner h2 {
  font-size: var(--font-size-3xl);
  font-weight: 700;
  margin-bottom: var(--spacing-sm);
}

.promo-banner p {
  font-size: var(--font-size-lg);
  opacity: 0.85;
  margin-bottom: var(--spacing-lg);
}

/* --- Quick Links --- */
.quick-links {
  display: flex;
  gap: var(--spacing-lg);
  justify-content: center;
  flex-wrap: wrap;
  padding: var(--spacing-xl) var(--spacing-lg);
}

.quick-link {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-sm);
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--color-link);
}

.quick-link svg {
  width: 16px;
  height: 16px;
  stroke: currentColor;
  stroke-width: 2;
  fill: none;
}

/* --- Audio Promo --- */
.audio-promo {
  font-size: var(--font-size-sm);
  color: var(--color-secondary);
  margin-bottom: var(--spacing-lg);
}

.audio-promo a { font-weight: 500; }

/* --- Footer --- */
.site-footer {
  background: var(--color-bg);
  padding: var(--spacing-xl) var(--spacing-lg) var(--spacing-lg);
  font-size: var(--font-size-xs);
  color: var(--color-secondary);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.footer-legal {
  padding-bottom: var(--spacing-md);
  border-bottom: 1px solid var(--color-border);
  margin-bottom: var(--spacing-md);
  line-height: 1.6;
}

.footer-columns {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--spacing-xl);
  padding-bottom: var(--spacing-xl);
  border-bottom: 1px solid var(--color-border);
  margin-bottom: var(--spacing-md);
}

.footer-col h4 {
  font-size: var(--font-size-xs);
  font-weight: 600;
  color: var(--color-dark);
  margin-bottom: var(--spacing-sm);
  cursor: default;
}

.footer-col ul li {
  margin-bottom: var(--spacing-xs);
}

.footer-col ul li a {
  color: var(--color-secondary);
  font-size: var(--font-size-xs);
  transition: color var(--transition-fast);
}

.footer-col ul li a:hover { color: var(--color-dark); }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--spacing-sm);
}

.footer-bottom-legal {
  font-size: var(--font-size-xs);
}

/* Mobile footer accordion */
.footer-accordion-toggle {
  display: none;
  width: 100%;
  justify-content: space-between;
  align-items: center;
  padding: var(--spacing-sm) 0;
  border: none;
  background: none;
  cursor: pointer;
}

.footer-accordion-toggle h4 {
  font-size: var(--font-size-xs);
  font-weight: 600;
  color: var(--color-dark);
}

.footer-accordion-toggle svg {
  width: 14px;
  height: 14px;
  stroke: var(--color-dark);
  stroke-width: 2;
  fill: none;
  transition: transform var(--transition-base);
}

.footer-col-content {
  overflow: hidden;
}

.footer-col.open .footer-accordion-toggle svg {
  transform: rotate(180deg);
}

/* --- Section anchor targets for smooth scroll --- */
.section-anchor {
  scroll-margin-top: calc(var(--nav-height) + var(--section-nav-height) + var(--spacing-md));
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .product-grid {
    grid-template-columns: 1fr;
    max-width: 680px;
  }

  .hero-tile { min-height: 420px; }

  .section-headline { font-size: var(--font-size-2xl); }
  .category-hero h1 { font-size: var(--font-size-3xl); }

  .footer-columns {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  :root {
    --carousel-card-width: 240px;
  }

  .top-nav-links { display: none; }
  .nav-hamburger { display: block; }

  .section { padding: var(--spacing-2xl) var(--spacing-md); }

  .section-headline {
    font-size: var(--font-size-2xl);
  }

  .section-subheadline {
    font-size: var(--font-size-base);
  }

  .store-hero h1 { font-size: var(--font-size-3xl); }
  .category-hero h1 { font-size: var(--font-size-3xl); }

  .product-grid {
    padding: 0 var(--spacing-md) var(--spacing-2xl);
    gap: var(--spacing-md);
  }

  .hero-tile {
    min-height: 380px;
    padding: var(--spacing-2xl) var(--spacing-lg) var(--spacing-lg);
  }

  .hero-tile-name { font-size: var(--font-size-2xl); }
  .hero-tile-tagline { font-size: var(--font-size-base); }

  .entertainment-cards {
    grid-template-columns: repeat(2, 1fr);
  }

  .product-icon-bar-inner {
    justify-content: flex-start;
    padding-bottom: var(--spacing-sm);
  }

  .section-nav-inner {
    justify-content: flex-start;
  }

  /* Footer accordion on mobile */
  .footer-columns {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .footer-accordion-toggle {
    display: flex;
  }

  .footer-col {
    border-bottom: 1px solid var(--color-border);
  }

  .footer-col-content {
    max-height: 0;
    transition: max-height var(--transition-base);
  }

  .footer-col.open .footer-col-content {
    max-height: 400px;
  }
}

@media (max-width: 480px) {
  .hero-tile { min-height: 340px; }
  .hero-tile-name { font-size: var(--font-size-xl); }
  .hero-tile-tagline { font-size: var(--font-size-sm); }

  .entertainment-cards {
    grid-template-columns: 1fr;
  }

  .entertainment-tabs {
    gap: var(--spacing-xs);
  }

  .entertainment-tab {
    font-size: var(--font-size-sm);
    padding: var(--spacing-sm) var(--spacing-md);
  }
}

/* --- Reduced Motion --- */
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

/* --- Print --- */
@media print {
  .top-nav, .section-nav, .carousel-btn { display: none; }
  .carousel-track { overflow: visible; flex-wrap: wrap; }
}
