/* ========================================
   Orchard — Shared Design System
   ======================================== */

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-dark: #1d1d1f;
  --color-secondary: #6e6e73;
  --color-link: #0066cc;
  --color-link-hover: #004499;
  --color-bg: #f5f5f7;
  --color-white: #ffffff;
  --color-ribbon-bg: #1d1d1f;
  --color-ribbon-text: #f5f5f7;
  --color-card-bg: #fbfbfd;
  --color-border: #d2d2d7;
  --color-badge: #bf4800;
  --color-badge-bg: #fff4e6;

  --font-stack: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  --font-size-xs: 12px;
  --font-size-sm: 14px;
  --font-size-base: 16px;
  --font-size-md: 18px;
  --font-size-lg: 21px;
  --font-size-xl: 28px;
  --font-size-2xl: 36px;
  --font-size-3xl: 40px;
  --font-size-4xl: 48px;
  --font-size-5xl: 56px;

  --line-height: 1.47;
  --spacing-xs: 4px;
  --spacing-sm: 8px;
  --spacing-md: 16px;
  --spacing-lg: 24px;
  --spacing-xl: 32px;
  --spacing-2xl: 48px;
  --spacing-3xl: 64px;
  --spacing-4xl: 80px;

  --nav-height: 44px;
  --section-nav-height: 52px;
  --max-width: 1200px;
  --carousel-card-width: 280px;
  --carousel-gap: 16px;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --radius-xl: 24px;

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  --shadow-card: 0 2px 12px rgba(0,0,0,0.08);
  --shadow-elevated: 0 4px 24px rgba(0,0,0,0.12);
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-stack);
  font-size: var(--font-size-base);
  line-height: var(--line-height);
  color: var(--color-dark);
  background: var(--color-white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

a { color: var(--color-link); text-decoration: none; cursor: pointer; }
a:hover { text-decoration: underline; color: var(--color-link-hover); }
img { display: block; max-width: 100%; height: auto; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }

/* --- Skip Link --- */
.skip-link {
  position: absolute;
  top: -100%;
  left: 0;
  background: var(--color-dark);
  color: var(--color-white);
  padding: var(--spacing-sm) var(--spacing-md);
  z-index: 9999;
}
.skip-link:focus { top: 0; }

/* --- Top Navigation --- */
.top-nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(29,29,31,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  height: var(--nav-height);
}

.top-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  padding: 0 var(--spacing-lg);
}

.top-nav-logo {
  color: var(--color-white);
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.02em;
  opacity: 0.9;
}
.top-nav-logo:hover { opacity: 1; text-decoration: none; }

.top-nav-links {
  display: flex;
  align-items: center;
  gap: var(--spacing-lg);
}

.top-nav-links a {
  color: rgba(245,245,247,0.8);
  font-size: var(--font-size-xs);
  font-weight: 400;
  letter-spacing: 0;
  transition: color var(--transition-fast);
}
.top-nav-links a:hover { color: var(--color-white); text-decoration: none; }

.nav-hamburger {
  display: none;
  color: var(--color-white);
  padding: var(--spacing-sm);
}

/* --- Ribbon Banner --- */
.ribbon-banner {
  background: var(--color-ribbon-bg);
  color: var(--color-ribbon-text);
  text-align: center;
  padding: var(--spacing-sm) var(--spacing-md);
  font-size: var(--font-size-sm);
  line-height: 1.5;
}

.ribbon-banner a {
  color: var(--color-link);
  font-weight: 500;
}

/* --- Section Utilities --- */
.section {
  padding: var(--spacing-3xl) var(--spacing-lg);
}

.section-dark {
  background: var(--color-bg);
}

.section-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.section-headline {
  font-size: var(--font-size-3xl);
  font-weight: 700;
  letter-spacing: -0.025em;
  color: var(--color-dark);
  margin-bottom: var(--spacing-sm);
}

.section-subheadline {
  font-size: var(--font-size-lg);
  font-weight: 400;
  color: var(--color-secondary);
  margin-bottom: var(--spacing-xl);
}

.section-headline-center,
.section-subheadline-center {
  text-align: center;
}

/* --- Carousel --- */
.carousel-wrapper {
  position: relative;
}

.carousel-track {
  display: flex;
  gap: var(--carousel-gap);
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: var(--spacing-sm) 0;
}

.carousel-track::-webkit-scrollbar { display: none; }

.carousel-track--padded {
  padding-left: calc((100% - var(--max-width)) / 2 + var(--spacing-lg));
  padding-right: var(--spacing-lg);
}

@media (max-width: 1264px) {
  .carousel-track--padded {
    padding-left: var(--spacing-lg);
  }
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--color-white);
  box-shadow: var(--shadow-elevated);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: opacity var(--transition-fast), transform var(--transition-fast);
  opacity: 0;
}

.carousel-wrapper:hover .carousel-btn,
.carousel-btn:focus {
  opacity: 1;
}

.carousel-btn:hover {
  transform: translateY(-50%) scale(1.08);
}

.carousel-btn--prev { left: -8px; }
.carousel-btn--next { right: -8px; }

.carousel-btn svg {
  width: 18px;
  height: 18px;
  stroke: var(--color-dark);
  stroke-width: 2.5;
  fill: none;
}

/* --- Product Card (Carousel) --- */
.product-card {
  flex: 0 0 var(--carousel-card-width);
  scroll-snap-align: start;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.product-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-elevated);
}

.product-card-image {
  width: 100%;
  height: 240px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--color-bg);
  position: relative;
  overflow: hidden;
}

.product-card-badge {
  position: absolute;
  top: var(--spacing-sm);
  left: var(--spacing-sm);
  background: var(--color-badge-bg);
  color: var(--color-badge);
  font-size: var(--font-size-xs);
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 4px;
  letter-spacing: 0.02em;
}

.product-card-image .product-icon {
  font-size: 64px;
  opacity: 0.15;
  user-select: none;
}

.product-card-body {
  padding: var(--spacing-md) var(--spacing-md) var(--spacing-lg);
}

.product-card-name {
  font-size: var(--font-size-md);
  font-weight: 600;
  color: var(--color-dark);
  margin-bottom: var(--spacing-xs);
}

.product-card-tagline {
  font-size: var(--font-size-sm);
  color: var(--color-secondary);
  margin-bottom: var(--spacing-sm);
  line-height: 1.4;
}

.product-card-price {
  font-size: var(--font-size-base);
  font-weight: 600;
  color: var(--color-dark);
  margin-bottom: var(--spacing-xs);
}

.product-card-monthly {
  font-size: var(--font-size-xs);
  color: var(--color-secondary);
}

.product-card-links {
  display: flex;
  gap: var(--spacing-md);
  margin-top: var(--spacing-sm);
}

.product-card-links a {
  font-size: var(--font-size-sm);
  font-weight: 500;
}

/* --- Help / Benefit / Guide Cards --- */
.info-card {
  flex: 0 0 var(--carousel-card-width);
  scroll-snap-align: start;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  padding: var(--spacing-lg);
  display: flex;
  flex-direction: column;
}

.info-card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--spacing-md);
  flex-shrink: 0;
}

.info-card-icon svg {
  width: 24px;
  height: 24px;
  stroke: var(--color-dark);
  stroke-width: 1.5;
  fill: none;
}

.info-card-title {
  font-size: var(--font-size-base);
  font-weight: 600;
  color: var(--color-dark);
  margin-bottom: var(--spacing-sm);
}

.info-card-desc {
  font-size: var(--font-size-sm);
  color: var(--color-secondary);
  line-height: 1.45;
  flex: 1;
}

.info-card-link {
  margin-top: var(--spacing-md);
  font-size: var(--font-size-sm);
  font-weight: 500;
}

/* --- Hero Product Grid (Homepage) --- */
.product-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--spacing-md);
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--spacing-lg) var(--spacing-3xl);
}

.hero-tile {
  position: relative;
  border-radius: var(--radius-xl);
  overflow: hidden;
  min-height: 500px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: var(--spacing-3xl) var(--spacing-xl) var(--spacing-xl);
  cursor: default;
}

.hero-tile--dark {
  background: var(--color-dark);
  color: var(--color-white);
}

.hero-tile--light {
  background: var(--color-bg);
  color: var(--color-dark);
}

.hero-tile--gradient-warm {
  background: linear-gradient(135deg, #fef3e2 0%, #fde8c8 50%, #f9d5a0 100%);
  color: var(--color-dark);
}

.hero-tile--gradient-cool {
  background: linear-gradient(135deg, #e8f4f8 0%, #d1ecf9 50%, #b8e0f4 100%);
  color: var(--color-dark);
}

.hero-tile--gradient-purple {
  background: linear-gradient(135deg, #f0e8f7 0%, #e4d6f0 50%, #d4c0e8 100%);
  color: var(--color-dark);
}

.hero-tile--gradient-green {
  background: linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 50%, #a5d6a7 100%);
  color: var(--color-dark);
}

.hero-tile-name {
  font-size: var(--font-size-3xl);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: var(--spacing-sm);
}

.hero-tile-tagline {
  font-size: var(--font-size-lg);
  font-weight: 400;
  opacity: 0.85;
  margin-bottom: var(--spacing-lg);
  max-width: 400px;
}

.hero-tile-ctas {
  display: flex;
  gap: var(--spacing-lg);
}

.cta-link {
  font-size: var(--font-size-base);
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.cta-link--light { color: var(--color-link); }
.cta-link--light:hover { color: var(--color-link-hover); }

.cta-link--white { color: var(--color-link); }
.cta-link--white:hover { color: #3399ff; text-decoration: underline; }

.cta-link svg {
  width: 14px;
  height: 14px;
  stroke: currentColor;
  stroke-width: 2;
  fill: none;
}

.hero-tile-image {
  margin-top: auto;
  width: 70%;
  max-width: 360px;
  height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.hero-tile-image .product-silhouette {
  font-size: 100px;
  opacity: 0.12;
  user-select: none;
}

/* --- Entertainment Tabs --- */
.entertainment-section {
  background: var(--color-bg);
  padding: var(--spacing-3xl) var(--spacing-lg);
}

.entertainment-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.entertainment-tabs {
  display: flex;
  gap: var(--spacing-sm);
  margin-bottom: var(--spacing-xl);
  border-bottom: 1px solid var(--color-border);
  padding-bottom: var(--spacing-sm);
}

.entertainment-tab {
  padding: var(--spacing-sm) var(--spacing-lg);
  font-size: var(--font-size-base);
  font-weight: 500;
  color: var(--color-secondary);
  border-radius: var(--radius-sm) var(--radius-sm) 0 0;
  transition: color var(--transition-fast), border-color var(--transition-fast);
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
}

.entertainment-tab:hover {
  color: var(--color-dark);
}

.entertainment-tab.active {
  color: var(--color-dark);
  border-bottom-color: var(--color-dark);
}

.entertainment-panel {
  display: none;
}

.entertainment-panel.active {
  display: block;
}

.entertainment-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--spacing-md);
}

.entertainment-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--color-white);
  box-shadow: var(--shadow-card);
  transition: transform var(--transition-base);
}

.entertainment-card:hover {
  transform: translateY(-2px);
}

.entertainment-card-image {
  width: 100%;
  height: 140px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 40px;
  opacity: 0.3;
}

.entertainment-card-body {
  padding: var(--spacing-md);
}

.entertainment-card-title {
  font-size: var(--font-size-sm);
  font-weight: 600;
  color: var(--color-dark);
  margin-bottom: var(--spacing-xs);
}

.entertainment-card-cta {
  font-size: var(--font-size-xs);
  font-weight: 500;
}

/* --- Store Hero --- */
.store-hero {
  text-align: center;
  padding: var(--spacing-4xl) var(--spacing-lg);
  background: var(--color-white);
}

.store-hero h1 {
  font-size: var(--font-size-4xl);
  font-weight: 700;
  letter-spacing: -0.03em;
  margin-bottom: var(--spacing-sm);
}

.store-hero p {
  font-size: var(--font-size-lg);
  color: var(--color-secondary);
  margin-bottom: var(--spacing-lg);
}

.store-hero-links {
  display: flex;
  gap: var(--spacing-lg);
  justify-content: center;
  flex-wrap: wrap;
}

/* --- Product Icon Bar --- */
.product-icon-bar {
  padding: var(--spacing-xl) var(--spacing-lg);
  background: var(--color-white);
  border-bottom: 1px solid rgba(0,0,0,0.06);
}

.product-icon-bar-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  gap: var(--spacing-xl);
  overflow-x: auto;
  scrollbar-width: none;
  justify-content: center;
}

.product-icon-bar-inner::-webkit-scrollbar { display: none; }

.product-icon-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--spacing-sm);
  text-decoration: none;
  flex-shrink: 0;
  transition: opacity var(--transition-fast);
}

.product-icon-item:hover { opacity: 0.7; text-decoration: none; }

.product-icon-item .icon-circle {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
}

.product-icon-item .icon-circle svg {
  width: 26px;
  height: 26px;
  stroke: var(--color-dark);
  stroke-width: 1.5;
  fill: none;
}

.product-icon-item span {
  font-size: var(--font-size-xs);
  color: var(--color-dark);
  font-weight: 400;
  text-align: center;
  white-space: nowrap;
}

/* --- Category Hero --- */
.category-hero {
  text-align: center;
  padding: var(--spacing-4xl) var(--spacing-lg) var(--spacing-2xl);
}

.category-hero h1 {
  font-size: var(--font-size-5xl);
  font-weight: 700;
  letter-spacing: -0.03em;
  margin-bottom: var(--spacing-sm);
}

.category-hero p {
  font-size: var(--font-size-lg);
  color: var(--color-secondary);
}

/* --- Sticky Section Nav --- */
.section-nav {
  position: sticky;
  top: var(--nav-height);
  z-index: 900;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0,0,0,0.08);
}

.section-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  gap: var(--spacing-xl);
  overflow-x: auto;
  scrollbar-width: none;
  padding: var(--spacing-sm) var(--spacing-lg);
}

.section-nav-inner::-webkit-scrollbar { display: none; }

.section-nav a {
  font-size: var(--font-size-sm);
  font-weight: 400;
  color: var(--color-secondary);
  white-space: nowrap;
  padding: var(--spacing-sm) 0;
  border-bottom: 2px solid transparent;
  transition: color var(--transition-fast), border-color var(--transition-fast);
  text-decoration: none;
}

.section-nav a:hover {
  color: var(--color-dark);
  text-decoration: none;
}

.section-nav a.active {
  color: var(--color-dark);
  border-bottom-color: var(--color-dark);
  font-weight: 500;
}

/* --- Promo Banner (Brand Collab, etc.) --- */
.promo-banner {
  border-radius: var(--radius-xl);
  overflow: hidden;
  padding: var(--spacing-3xl);
  text-align: center;
  margin: 0 auto;
  max-width: var(--max-width);
}

.promo-banner--dark {
  background: var(--color-dark);
  color: var(--color-white);
}

.promo-banner--gradient {
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
  color: var(--color-white);
}

.promo-banner h2 {
  font-size: var(--font-size-3xl);
  font-weight: 700;
  margin-bottom: var(--spacing-sm);
}

.promo-banner p {
  font-size: var(--font-size-lg);
  opacity: 0.85;
  margin-bottom: var(--spacing-lg);
}

/* --- Quick Links --- */
.quick-links {
  display: flex;
  gap: var(--spacing-lg);
  justify-content: center;
  flex-wrap: wrap;
  padding: var(--spacing-xl) var(--spacing-lg);
}

.quick-link {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-sm);
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--color-link);
}

.quick-link svg {
  width: 16px;
  height: 16px;
  stroke: currentColor;
  stroke-width: 2;
  fill: none;
}

/* --- Audio Promo --- */
.audio-promo {
  font-size: var(--font-size-sm);
  color: var(--color-secondary);
  margin-bottom: var(--spacing-lg);
}

.audio-promo a { font-weight: 500; }

/* --- Footer --- */
.site-footer {
  background: var(--color-bg);
  padding: var(--spacing-xl) var(--spacing-lg) var(--spacing-lg);
  font-size: var(--font-size-xs);
  color: var(--color-secondary);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.footer-legal {
  padding-bottom: var(--spacing-md);
  border-bottom: 1px solid var(--color-border);
  margin-bottom: var(--spacing-md);
  line-height: 1.6;
}

.footer-columns {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--spacing-xl);
  padding-bottom: var(--spacing-xl);
  border-bottom: 1px solid var(--color-border);
  margin-bottom: var(--spacing-md);
}

.footer-col h4 {
  font-size: var(--font-size-xs);
  font-weight: 600;
  color: var(--color-dark);
  margin-bottom: var(--spacing-sm);
  cursor: default;
}

.footer-col ul li {
  margin-bottom: var(--spacing-xs);
}

.footer-col ul li a {
  color: var(--color-secondary);
  font-size: var(--font-size-xs);
  transition: color var(--transition-fast);
}

.footer-col ul li a:hover { color: var(--color-dark); }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--spacing-sm);
}

.footer-bottom-legal {
  font-size: var(--font-size-xs);
}

/* Mobile footer accordion */
.footer-accordion-toggle {
  display: none;
  width: 100%;
  justify-content: space-between;
  align-items: center;
  padding: var(--spacing-sm) 0;
  border: none;
  background: none;
  cursor: pointer;
}

.footer-accordion-toggle h4 {
  font-size: var(--font-size-xs);
  font-weight: 600;
  color: var(--color-dark);
}

.footer-accordion-toggle svg {
  width: 14px;
  height: 14px;
  stroke: var(--color-dark);
  stroke-width: 2;
  fill: none;
  transition: transform var(--transition-base);
}

.footer-col-content {
  overflow: hidden;
}

.footer-col.open .footer-accordion-toggle svg {
  transform: rotate(180deg);
}

/* --- Section anchor targets for smooth scroll --- */
.section-anchor {
  scroll-margin-top: calc(var(--nav-height) + var(--section-nav-height) + var(--spacing-md));
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .product-grid {
    grid-template-columns: 1fr;
    max-width: 680px;
  }

  .hero-tile { min-height: 420px; }

  .section-headline { font-size: var(--font-size-2xl); }
  .category-hero h1 { font-size: var(--font-size-3xl); }

  .footer-columns {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  :root {
    --carousel-card-width: 240px;
  }

  .top-nav-links { display: none; }
  .nav-hamburger { display: block; }

  .section { padding: var(--spacing-2xl) var(--spacing-md); }

  .section-headline {
    font-size: var(--font-size-2xl);
  }

  .section-subheadline {
    font-size: var(--font-size-base);
  }

  .store-hero h1 { font-size: var(--font-size-3xl); }
  .category-hero h1 { font-size: var(--font-size-3xl); }

  .product-grid {
    padding: 0 var(--spacing-md) var(--spacing-2xl);
    gap: var(--spacing-md);
  }

  .hero-tile {
    min-height: 380px;
    padding: var(--spacing-2xl) var(--spacing-lg) var(--spacing-lg);
  }

  .hero-tile-name { font-size: var(--font-size-2xl); }
  .hero-tile-tagline { font-size: var(--font-size-base); }

  .entertainment-cards {
    grid-template-columns: repeat(2, 1fr);
  }

  .product-icon-bar-inner {
    justify-content: flex-start;
    padding-bottom: var(--spacing-sm);
  }

  .section-nav-inner {
    justify-content: flex-start;
  }

  /* Footer accordion on mobile */
  .footer-columns {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .footer-accordion-toggle {
    display: flex;
  }

  .footer-col {
    border-bottom: 1px solid var(--color-border);
  }

  .footer-col-content {
    max-height: 0;
    transition: max-height var(--transition-base);
  }

  .footer-col.open .footer-col-content {
    max-height: 400px;
  }
}

@media (max-width: 480px) {
  .hero-tile { min-height: 340px; }
  .hero-tile-name { font-size: var(--font-size-xl); }
  .hero-tile-tagline { font-size: var(--font-size-sm); }

  .entertainment-cards {
    grid-template-columns: 1fr;
  }

  .entertainment-tabs {
    gap: var(--spacing-xs);
  }

  .entertainment-tab {
    font-size: var(--font-size-sm);
    padding: var(--spacing-sm) var(--spacing-md);
  }
}

/* --- Reduced Motion --- */
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

/* --- Print --- */
@media print {
  .top-nav, .section-nav, .carousel-btn { display: none; }
  .carousel-track { overflow: visible; flex-wrap: wrap; }
}

/* ========================================
   Orchard — Shared Design System
   ======================================== */

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-dark: #1d1d1f;
  --color-secondary: #6e6e73;
  --color-link: #0066cc;
  --color-link-hover: #004499;
  --color-bg: #f5f5f7;
  --color-white: #ffffff;
  --color-ribbon-bg: #1d1d1f;
  --color-ribbon-text: #f5f5f7;
  --color-card-bg: #fbfbfd;
  --color-border: #d2d2d7;
  --color-badge: #bf4800;
  --color-badge-bg: #fff4e6;

  --font-stack: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  --font-size-xs: 12px;
  --font-size-sm: 14px;
  --font-size-base: 16px;
  --font-size-md: 18px;
  --font-size-lg: 21px;
  --font-size-xl: 28px;
  --font-size-2xl: 36px;
  --font-size-3xl: 40px;
  --font-size-4xl: 48px;
  --font-size-5xl: 56px;

  --line-height: 1.47;
  --spacing-xs: 4px;
  --spacing-sm: 8px;
  --spacing-md: 16px;
  --spacing-lg: 24px;
  --spacing-xl: 32px;
  --spacing-2xl: 48px;
  --spacing-3xl: 64px;
  --spacing-4xl: 80px;

  --nav-height: 44px;
  --section-nav-height: 52px;
  --max-width: 1200px;
  --carousel-card-width: 280px;
  --carousel-gap: 16px;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --radius-xl: 24px;

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  --shadow-card: 0 2px 12px rgba(0,0,0,0.08);
  --shadow-elevated: 0 4px 24px rgba(0,0,0,0.12);
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-stack);
  font-size: var(--font-size-base);
  line-height: var(--line-height);
  color: var(--color-dark);
  background: var(--color-white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

a { color: var(--color-link); text-decoration: none; cursor: pointer; }
a:hover { text-decoration: underline; color: var(--color-link-hover); }
img { display: block; max-width: 100%; height: auto; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }

/* --- Skip Link --- */
.skip-link {
  position: absolute;
  top: -100%;
  left: 0;
  background: var(--color-dark);
  color: var(--color-white);
  padding: var(--spacing-sm) var(--spacing-md);
  z-index: 9999;
}
.skip-link:focus { top: 0; }

/* --- Top Navigation --- */
.top-nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(29,29,31,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  height: var(--nav-height);
}

.top-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  padding: 0 var(--spacing-lg);
}

.top-nav-logo {
  color: var(--color-white);
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.02em;
  opacity: 0.9;
}
.top-nav-logo:hover { opacity: 1; text-decoration: none; }

.top-nav-links {
  display: flex;
  align-items: center;
  gap: var(--spacing-lg);
}

.top-nav-links a {
  color: rgba(245,245,247,0.8);
  font-size: var(--font-size-xs);
  font-weight: 400;
  letter-spacing: 0;
  transition: color var(--transition-fast);
}
.top-nav-links a:hover { color: var(--color-white); text-decoration: none; }

.nav-hamburger {
  display: none;
  color: var(--color-white);
  padding: var(--spacing-sm);
}

/* --- Ribbon Banner --- */
.ribbon-banner {
  background: var(--color-ribbon-bg);
  color: var(--color-ribbon-text);
  text-align: center;
  padding: var(--spacing-sm) var(--spacing-md);
  font-size: var(--font-size-sm);
  line-height: 1.5;
}

.ribbon-banner a {
  color: var(--color-link);
  font-weight: 500;
}

/* --- Section Utilities --- */
.section {
  padding: var(--spacing-3xl) var(--spacing-lg);
}

.section-dark {
  background: var(--color-bg);
}

.section-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.section-headline {
  font-size: var(--font-size-3xl);
  font-weight: 700;
  letter-spacing: -0.025em;
  color: var(--color-dark);
  margin-bottom: var(--spacing-sm);
}

.section-subheadline {
  font-size: var(--font-size-lg);
  font-weight: 400;
  color: var(--color-secondary);
  margin-bottom: var(--spacing-xl);
}

.section-headline-center,
.section-subheadline-center {
  text-align: center;
}

/* --- Carousel --- */
.carousel-wrapper {
  position: relative;
}

.carousel-track {
  display: flex;
  gap: var(--carousel-gap);
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: var(--spacing-sm) 0;
}

.carousel-track::-webkit-scrollbar { display: none; }

.carousel-track--padded {
  padding-left: calc((100% - var(--max-width)) / 2 + var(--spacing-lg));
  padding-right: var(--spacing-lg);
}

@media (max-width: 1264px) {
  .carousel-track--padded {
    padding-left: var(--spacing-lg);
  }
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--color-white);
  box-shadow: var(--shadow-elevated);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: opacity var(--transition-fast), transform var(--transition-fast);
  opacity: 0;
}

.carousel-wrapper:hover .carousel-btn,
.carousel-btn:focus {
  opacity: 1;
}

.carousel-btn:hover {
  transform: translateY(-50%) scale(1.08);
}

.carousel-btn--prev { left: -8px; }
.carousel-btn--next { right: -8px; }

.carousel-btn svg {
  width: 18px;
  height: 18px;
  stroke: var(--color-dark);
  stroke-width: 2.5;
  fill: none;
}

/* --- Product Card (Carousel) --- */
.product-card {
  flex: 0 0 var(--carousel-card-width);
  scroll-snap-align: start;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.product-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-elevated);
}

.product-card-image {
  width: 100%;
  height: 240px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--color-bg);
  position: relative;
  overflow: hidden;
}

.product-card-badge {
  position: absolute;
  top: var(--spacing-sm);
  left: var(--spacing-sm);
  background: var(--color-badge-bg);
  color: var(--color-badge);
  font-size: var(--font-size-xs);
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 4px;
  letter-spacing: 0.02em;
}

.product-card-image .product-icon {
  font-size: 64px;
  opacity: 0.15;
  user-select: none;
}

.product-card-body {
  padding: var(--spacing-md) var(--spacing-md) var(--spacing-lg);
}

.product-card-name {
  font-size: var(--font-size-md);
  font-weight: 600;
  color: var(--color-dark);
  margin-bottom: var(--spacing-xs);
}

.product-card-tagline {
  font-size: var(--font-size-sm);
  color: var(--color-secondary);
  margin-bottom: var(--spacing-sm);
  line-height: 1.4;
}

.product-card-price {
  font-size: var(--font-size-base);
  font-weight: 600;
  color: var(--color-dark);
  margin-bottom: var(--spacing-xs);
}

.product-card-monthly {
  font-size: var(--font-size-xs);
  color: var(--color-secondary);
}

.product-card-links {
  display: flex;
  gap: var(--spacing-md);
  margin-top: var(--spacing-sm);
}

.product-card-links a {
  font-size: var(--font-size-sm);
  font-weight: 500;
}

/* --- Help / Benefit / Guide Cards --- */
.info-card {
  flex: 0 0 var(--carousel-card-width);
  scroll-snap-align: start;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  padding: var(--spacing-lg);
  display: flex;
  flex-direction: column;
}

.info-card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--spacing-md);
  flex-shrink: 0;
}

.info-card-icon svg {
  width: 24px;
  height: 24px;
  stroke: var(--color-dark);
  stroke-width: 1.5;
  fill: none;
}

.info-card-title {
  font-size: var(--font-size-base);
  font-weight: 600;
  color: var(--color-dark);
  margin-bottom: var(--spacing-sm);
}

.info-card-desc {
  font-size: var(--font-size-sm);
  color: var(--color-secondary);
  line-height: 1.45;
  flex: 1;
}

.info-card-link {
  margin-top: var(--spacing-md);
  font-size: var(--font-size-sm);
  font-weight: 500;
}

/* --- Hero Product Grid (Homepage) --- */
.product-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--spacing-md);
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--spacing-lg) var(--spacing-3xl);
}

.hero-tile {
  position: relative;
  border-radius: var(--radius-xl);
  overflow: hidden;
  min-height: 500px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: var(--spacing-3xl) var(--spacing-xl) var(--spacing-xl);
  cursor: default;
}

.hero-tile--dark {
  background: var(--color-dark);
  color: var(--color-white);
}

.hero-tile--light {
  background: var(--color-bg);
  color: var(--color-dark);
}

.hero-tile--gradient-warm {
  background: linear-gradient(135deg, #fef3e2 0%, #fde8c8 50%, #f9d5a0 100%);
  color: var(--color-dark);
}

.hero-tile--gradient-cool {
  background: linear-gradient(135deg, #e8f4f8 0%, #d1ecf9 50%, #b8e0f4 100%);
  color: var(--color-dark);
}

.hero-tile--gradient-purple {
  background: linear-gradient(135deg, #f0e8f7 0%, #e4d6f0 50%, #d4c0e8 100%);
  color: var(--color-dark);
}

.hero-tile--gradient-green {
  background: linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 50%, #a5d6a7 100%);
  color: var(--color-dark);
}

.hero-tile-name {
  font-size: var(--font-size-3xl);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: var(--spacing-sm);
}

.hero-tile-tagline {
  font-size: var(--font-size-lg);
  font-weight: 400;
  opacity: 0.85;
  margin-bottom: var(--spacing-lg);
  max-width: 400px;
}

.hero-tile-ctas {
  display: flex;
  gap: var(--spacing-lg);
}

.cta-link {
  font-size: var(--font-size-base);
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.cta-link--light { color: var(--color-link); }
.cta-link--light:hover { color: var(--color-link-hover); }

.cta-link--white { color: var(--color-link); }
.cta-link--white:hover { color: #3399ff; text-decoration: underline; }

.cta-link svg {
  width: 14px;
  height: 14px;
  stroke: currentColor;
  stroke-width: 2;
  fill: none;
}

.hero-tile-image {
  margin-top: auto;
  width: 70%;
  max-width: 360px;
  height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.hero-tile-image .product-silhouette {
  font-size: 100px;
  opacity: 0.12;
  user-select: none;
}

/* --- Entertainment Tabs --- */
.entertainment-section {
  background: var(--color-bg);
  padding: var(--spacing-3xl) var(--spacing-lg);
}

.entertainment-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.entertainment-tabs {
  display: flex;
  gap: var(--spacing-sm);
  margin-bottom: var(--spacing-xl);
  border-bottom: 1px solid var(--color-border);
  padding-bottom: var(--spacing-sm);
}

.entertainment-tab {
  padding: var(--spacing-sm) var(--spacing-lg);
  font-size: var(--font-size-base);
  font-weight: 500;
  color: var(--color-secondary);
  border-radius: var(--radius-sm) var(--radius-sm) 0 0;
  transition: color var(--transition-fast), border-color var(--transition-fast);
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
}

.entertainment-tab:hover {
  color: var(--color-dark);
}

.entertainment-tab.active {
  color: var(--color-dark);
  border-bottom-color: var(--color-dark);
}

.entertainment-panel {
  display: none;
}

.entertainment-panel.active {
  display: block;
}

.entertainment-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--spacing-md);
}

.entertainment-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--color-white);
  box-shadow: var(--shadow-card);
  transition: transform var(--transition-base);
}

.entertainment-card:hover {
  transform: translateY(-2px);
}

.entertainment-card-image {
  width: 100%;
  height: 140px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 40px;
  opacity: 0.3;
}

.entertainment-card-body {
  padding: var(--spacing-md);
}

.entertainment-card-title {
  font-size: var(--font-size-sm);
  font-weight: 600;
  color: var(--color-dark);
  margin-bottom: var(--spacing-xs);
}

.entertainment-card-cta {
  font-size: var(--font-size-xs);
  font-weight: 500;
}

/* --- Store Hero --- */
.store-hero {
  text-align: center;
  padding: var(--spacing-4xl) var(--spacing-lg);
  background: var(--color-white);
}

.store-hero h1 {
  font-size: var(--font-size-4xl);
  font-weight: 700;
  letter-spacing: -0.03em;
  margin-bottom: var(--spacing-sm);
}

.store-hero p {
  font-size: var(--font-size-lg);
  color: var(--color-secondary);
  margin-bottom: var(--spacing-lg);
}

.store-hero-links {
  display: flex;
  gap: var(--spacing-lg);
  justify-content: center;
  flex-wrap: wrap;
}

/* --- Product Icon Bar --- */
.product-icon-bar {
  padding: var(--spacing-xl) var(--spacing-lg);
  background: var(--color-white);
  border-bottom: 1px solid rgba(0,0,0,0.06);
}

.product-icon-bar-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  gap: var(--spacing-xl);
  overflow-x: auto;
  scrollbar-width: none;
  justify-content: center;
}

.product-icon-bar-inner::-webkit-scrollbar { display: none; }

.product-icon-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--spacing-sm);
  text-decoration: none;
  flex-shrink: 0;
  transition: opacity var(--transition-fast);
}

.product-icon-item:hover { opacity: 0.7; text-decoration: none; }

.product-icon-item .icon-circle {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
}

.product-icon-item .icon-circle svg {
  width: 26px;
  height: 26px;
  stroke: var(--color-dark);
  stroke-width: 1.5;
  fill: none;
}

.product-icon-item span {
  font-size: var(--font-size-xs);
  color: var(--color-dark);
  font-weight: 400;
  text-align: center;
  white-space: nowrap;
}

/* --- Category Hero --- */
.category-hero {
  text-align: center;
  padding: var(--spacing-4xl) var(--spacing-lg) var(--spacing-2xl);
}

.category-hero h1 {
  font-size: var(--font-size-5xl);
  font-weight: 700;
  letter-spacing: -0.03em;
  margin-bottom: var(--spacing-sm);
}

.category-hero p {
  font-size: var(--font-size-lg);
  color: var(--color-secondary);
}

/* --- Sticky Section Nav --- */
.section-nav {
  position: sticky;
  top: var(--nav-height);
  z-index: 900;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0,0,0,0.08);
}

.section-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  gap: var(--spacing-xl);
  overflow-x: auto;
  scrollbar-width: none;
  padding: var(--spacing-sm) var(--spacing-lg);
}

.section-nav-inner::-webkit-scrollbar { display: none; }

.section-nav a {
  font-size: var(--font-size-sm);
  font-weight: 400;
  color: var(--color-secondary);
  white-space: nowrap;
  padding: var(--spacing-sm) 0;
  border-bottom: 2px solid transparent;
  transition: color var(--transition-fast), border-color var(--transition-fast);
  text-decoration: none;
}

.section-nav a:hover {
  color: var(--color-dark);
  text-decoration: none;
}

.section-nav a.active {
  color: var(--color-dark);
  border-bottom-color: var(--color-dark);
  font-weight: 500;
}

/* --- Promo Banner (Brand Collab, etc.) --- */
.promo-banner {
  border-radius: var(--radius-xl);
  overflow: hidden;
  padding: var(--spacing-3xl);
  text-align: center;
  margin: 0 auto;
  max-width: var(--max-width);
}

.promo-banner--dark {
  background: var(--color-dark);
  color: var(--color-white);
}

.promo-banner--gradient {
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
  color: var(--color-white);
}

.promo-banner h2 {
  font-size: var(--font-size-3xl);
  font-weight: 700;
  margin-bottom: var(--spacing-sm);
}

.promo-banner p {
  font-size: var(--font-size-lg);
  opacity: 0.85;
  margin-bottom: var(--spacing-lg);
}

/* --- Quick Links --- */
.quick-links {
  display: flex;
  gap: var(--spacing-lg);
  justify-content: center;
  flex-wrap: wrap;
  padding: var(--spacing-xl) var(--spacing-lg);
}

.quick-link {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-sm);
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--color-link);
}

.quick-link svg {
  width: 16px;
  height: 16px;
  stroke: currentColor;
  stroke-width: 2;
  fill: none;
}

/* --- Audio Promo --- */
.audio-promo {
  font-size: var(--font-size-sm);
  color: var(--color-secondary);
  margin-bottom: var(--spacing-lg);
}

.audio-promo a { font-weight: 500; }

/* --- Footer --- */
.site-footer {
  background: var(--color-bg);
  padding: var(--spacing-xl) var(--spacing-lg) var(--spacing-lg);
  font-size: var(--font-size-xs);
  color: var(--color-secondary);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.footer-legal {
  padding-bottom: var(--spacing-md);
  border-bottom: 1px solid var(--color-border);
  margin-bottom: var(--spacing-md);
  line-height: 1.6;
}

.footer-columns {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--spacing-xl);
  padding-bottom: var(--spacing-xl);
  border-bottom: 1px solid var(--color-border);
  margin-bottom: var(--spacing-md);
}

.footer-col h4 {
  font-size: var(--font-size-xs);
  font-weight: 600;
  color: var(--color-dark);
  margin-bottom: var(--spacing-sm);
  cursor: default;
}

.footer-col ul li {
  margin-bottom: var(--spacing-xs);
}

.footer-col ul li a {
  color: var(--color-secondary);
  font-size: var(--font-size-xs);
  transition: color var(--transition-fast);
}

.footer-col ul li a:hover { color: var(--color-dark); }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--spacing-sm);
}

.footer-bottom-legal {
  font-size: var(--font-size-xs);
}

/* Mobile footer accordion */
.footer-accordion-toggle {
  display: none;
  width: 100%;
  justify-content: space-between;
  align-items: center;
  padding: var(--spacing-sm) 0;
  border: none;
  background: none;
  cursor: pointer;
}

.footer-accordion-toggle h4 {
  font-size: var(--font-size-xs);
  font-weight: 600;
  color: var(--color-dark);
}

.footer-accordion-toggle svg {
  width: 14px;
  height: 14px;
  stroke: var(--color-dark);
  stroke-width: 2;
  fill: none;
  transition: transform var(--transition-base);
}

.footer-col-content {
  overflow: hidden;
}

.footer-col.open .footer-accordion-toggle svg {
  transform: rotate(180deg);
}

/* --- Section anchor targets for smooth scroll --- */
.section-anchor {
  scroll-margin-top: calc(var(--nav-height) + var(--section-nav-height) + var(--spacing-md));
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .product-grid {
    grid-template-columns: 1fr;
    max-width: 680px;
  }

  .hero-tile { min-height: 420px; }

  .section-headline { font-size: var(--font-size-2xl); }
  .category-hero h1 { font-size: var(--font-size-3xl); }

  .footer-columns {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  :root {
    --carousel-card-width: 240px;
  }

  .top-nav-links { display: none; }
  .nav-hamburger { display: block; }

  .section { padding: var(--spacing-2xl) var(--spacing-md); }

  .section-headline {
    font-size: var(--font-size-2xl);
  }

  .section-subheadline {
    font-size: var(--font-size-base);
  }

  .store-hero h1 { font-size: var(--font-size-3xl); }
  .category-hero h1 { font-size: var(--font-size-3xl); }

  .product-grid {
    padding: 0 var(--spacing-md) var(--spacing-2xl);
    gap: var(--spacing-md);
  }

  .hero-tile {
    min-height: 380px;
    padding: var(--spacing-2xl) var(--spacing-lg) var(--spacing-lg);
  }

  .hero-tile-name { font-size: var(--font-size-2xl); }
  .hero-tile-tagline { font-size: var(--font-size-base); }

  .entertainment-cards {
    grid-template-columns: repeat(2, 1fr);
  }

  .product-icon-bar-inner {
    justify-content: flex-start;
    padding-bottom: var(--spacing-sm);
  }

  .section-nav-inner {
    justify-content: flex-start;
  }

  /* Footer accordion on mobile */
  .footer-columns {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .footer-accordion-toggle {
    display: flex;
  }

  .footer-col {
    border-bottom: 1px solid var(--color-border);
  }

  .footer-col-content {
    max-height: 0;
    transition: max-height var(--transition-base);
  }

  .footer-col.open .footer-col-content {
    max-height: 400px;
  }
}

@media (max-width: 480px) {
  .hero-tile { min-height: 340px; }
  .hero-tile-name { font-size: var(--font-size-xl); }
  .hero-tile-tagline { font-size: var(--font-size-sm); }

  .entertainment-cards {
    grid-template-columns: 1fr;
  }

  .entertainment-tabs {
    gap: var(--spacing-xs);
  }

  .entertainment-tab {
    font-size: var(--font-size-sm);
    padding: var(--spacing-sm) var(--spacing-md);
  }
}

/* --- Reduced Motion --- */
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

/* --- Print --- */
@media print {
  .top-nav, .section-nav, .carousel-btn { display: none; }
  .carousel-track { overflow: visible; flex-wrap: wrap; }
}

